import { v4 as uuidv4, v5 as uuidv5 } from 'uuid'

/** Fixed namespace for every deterministic id generated by this application. */
const NAMESPACE = '6f1d6c1e-3b0a-4f6e-9a55-0d6c2f1b7a10'

/** Random id for records created by the user. Generated on the client so an
 *  offline create keeps the same id through every retry. */
export function newId(): string {
  return uuidv4()
}

/** Deterministic id: the same name always yields the same id, on every device.
 *  Used wherever two devices (or a retry) must agree on "the same record". */
export function deterministicId(name: string): string {
  return uuidv5(name, NAMESPACE)
}

/** The occurrence generated when `taskId` is completed (or skipped). Because it
 *  depends only on the predecessor, completing the same occurrence twice, on
 *  two devices, or in a retried request can never create a second successor. */
export const successorTaskId = (taskId: string) => deterministicId(`task:${taskId}:next`)
export const templateSubtaskId = (taskId: string, index: number) =>
  deterministicId(`task:${taskId}:subtask:${index}`)
export const taskLabelId = (taskId: string, labelId: string) =>
  deterministicId(`task:${taskId}:label:${labelId}`)
export const settingId = (userId: string, key: string) => deterministicId(`user:${userId}:setting:${key}`)
export const defaultLabelId = (userId: string, name: string) =>
  deterministicId(`user:${userId}:default-label:${name}`)
